# ==============================================================================# 087_COMMERCIAL_DATA_COLLECTION_ENGINE.py## IOTEC COMMERCIAL DATA COLLECTION ENGINE## Missão:# Registrar a coleta bruta de dados comerciais.## NÃO normaliza.# NÃO qualifica.# NÃO altera os dados.## Apenas preserva o dataset original.# ==============================================================================from __future__ import annotationsimport sqlite3import jsonimport hashlibfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class CommercialDataCollectionEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_raw_dataset(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            dataset_id TEXT,            provider TEXT,            adapter TEXT,            capability TEXT,            mission_hash TEXT,            record_count INTEGER,            raw_payload TEXT,            status TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _hash(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def register_dataset(        self,        provider,        adapter,        capability,        mission_hash,        raw_payload,        metadata=None    ):        metadata=metadata or {}        timestamp=datetime.utcnow().isoformat()        dataset_id=hashlib.md5(            f"{timestamp}{mission_hash}".encode()        ).hexdigest()        payload={            "timestamp":timestamp,            "dataset_id":dataset_id,            "provider":provider,            "adapter":adapter,            "capability":capability,            "mission_hash":mission_hash,            "record_count":len(raw_payload),            "raw_payload":raw_payload,            "status":"RAW_CAPTURED",            "metadata":metadata        }        signature=self._hash({            **payload,            "raw_payload":"<RAW_DATA>"        })        self.conn.execute("""        INSERT INTO commercial_raw_dataset(            timestamp,            dataset_id,            provider,            adapter,            capability,            mission_hash,            record_count,            raw_payload,            status,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["timestamp"],            payload["dataset_id"],            payload["provider"],            payload["adapter"],            payload["capability"],            payload["mission_hash"],            payload["record_count"],            json.dumps(payload["raw_payload"],ensure_ascii=False),            payload["status"],            json.dumps(payload["metadata"],ensure_ascii=False),            signature        ))        self.conn.commit()        payload["hash"]=signature        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    engine=CommercialDataCollectionEngine()    dataset=engine.register_dataset(        provider="EMPRESARIAL_PROVIDER_001",        adapter="EMPRESARIAL_ADAPTER",        capability="BASE_EMPRESARIAL",        mission_hash="7cd8a681ed9542d7fd3f7aad4204888f89e6105dfcec6005bd8881e265070904",        raw_payload=[            {                "company":"EMPRESA DEMONSTRAÇÃO",                "city":"Fortaleza",                "segment":"Industrial"            }        ],        metadata={            "origin":"086_AUTONOMOUS_PROVIDER_RESOLUTION_ENGINE",            "collection":"TEST"        }    )    print("="*80)    print("COMMERCIAL RAW DATASET")    print("="*80)    for k,v in dataset.items():        if k=="raw_payload":            print(f"{k:22}: {len(v)} registro(s)")        else:            print(f"{k:22}: {v}")    print("="*80)